#!/usr/bin/env python3
"""
release_zips.py -- the STRICT per-line release zips of the workshop plugins (one zip per DWC line, never one universal zip).

    <Id>-<version>-dwc3.6.zip   dwcVersion "3.6" (and sbcDsfVersion "3.6"): DWC 3.6.x installs it, every other DWC refuses it
    <Id>-<version>-dwc3.7.zip   dwcVersion "3.7" (and sbcDsfVersion "3.7"): DWC 3.7.x installs it, every other DWC refuses it

DWC (3.6.3 src/plugins/index.ts checkVersion, 3.7.0 src/plugins/index.ts checkVersion) compares dwcVersion and sbcDsfVersion by PREFIX of the
dot-split strings, so "3.6" passes 3.6.x only and "3.7" 3.7.x only. A "3" would pass 3.5 and 3.8 as well, that is why the universal zip
(tools/universal_zip.py, deprecated) is not released any more. Evidence and layout: docs/DWC-LINES.md.

THIS FILE IS A COPY of TallerPlugins tools/release_zips.py (the service is another repository); keep the two identical
(tests/strict-zips.test.js compares them when the TallerPlugins checkout is next to this one).

This module is used by build.py (--dwc both, --check-release):
  * finalize_zip()   rewrites a line zip: manifest values of the line, no source maps, .gz companions of the big bundles;
  * guard_*()        the cheap run-time guard every bundle carries (wrong host: visible warning, plugin does not start);
  * check_zip()      the release check;
  * write_sums()     SHA256SUMS.txt of a release folder.
"""
import gzip
import hashlib
import io
import json
import os
import re
import zipfile

LINES = ("3.6", "3.7")
SERVICE_ID = "WorkshopService"
# the python library that talks to DSF must be of the same line as the server (docs/UPGRADE-3.7.md of WorkshopService)
DSF_PYTHON = {"3.6": "dsf-python==3.6.0", "3.7": "dsf-python==3.7.0"}
GZ_MIN_BYTES = 32 * 1024  # bundles at least this big carry a .gz companion (DWC's own builds ship them)
MAX_FILE_BYTES = 8 * 1024 * 1024
MAX_ZIP_BYTES = 16 * 1024 * 1024
ZIP_DATE = (1980, 1, 1, 0, 0, 0)  # fixed: the same sources give the same bytes

# names that must never be inside a release zip
FORBIDDEN = re.compile(
    r"(^|/)(__pycache__/|[^/]*\.pyc$|[^/]*secret[^/]*$|[^/]*\.log$|[^/]*\.db$|[^/]*\.bak$|config\.json$|\.env[^/]*$|workshop-users[^/]*$|"
    r"test_[^/]*\.py$|[^/]*\.test\.js$|\.git[^/]*$|node_modules/|[^/]*\.map$|[^/]*\.map\.gz$)"
)


# ---------------------------------------------------------------- run-time guard

def guard_condition(line):
    """JS expression that is true when the HOST is the wrong one for a bundle of `line`."""
    if line == "3.6":
        # DWC 3.6 has no window.DWC anywhere in its tree; a host that has it is a 3.7 (or later) page
        return 'typeof window !== "undefined" && !!window.DWC'
    return '!(typeof window !== "undefined" && window.DWC && /^3\\.7(\\.|$)/.test(String(window.DWC.version)))'


def _report(plugin_id, line):
    """JS statement (an IIFE) that tells, loudly, that the plugin does not start on this host. Texts are English on purpose: this runs
    before the plugin registered any catalog, on a host the plugin does not support."""
    msg = "%s %s build needs DWC %s.x and was not started on this DWC. Install the zip made for your DWC version." % (plugin_id, line, line)
    return (
        '(function (id, need, text) { var host = typeof window !== "undefined" && window.DWC ? String(window.DWC.version) : "3.6 or unknown"; '
        'console.error("[" + id + "] " + text + " (host " + host + ")"); '
        'try { var d = document.createElement("div"); d.setAttribute("role", "alert"); d.setAttribute("data-workshop-line-guard", need); '
        'd.style.cssText = "position:fixed;left:8px;bottom:8px;z-index:99999;max-width:90vw;padding:8px 12px;background:#b71c1c;color:#fff;font:14px sans-serif;border-radius:4px"; '
        'd.textContent = text; (document.body || document.documentElement).appendChild(d); } catch (e) { /* no DOM yet */ } })('
        + json.dumps(plugin_id) + ", " + json.dumps(line) + ", " + json.dumps(msg) + ");"
    )


def guard_inline(plugin_id, line):
    """Statement for the top of a hand-written plugin function (the 3.6 wrapper, the 3.7 IIFE, the official index.js IIFE): returns early."""
    return "if (" + guard_condition(line) + ") { " + _report(plugin_id, line) + " return; }"


def guard_module(plugin_id, line):
    """Module imported FIRST by the index.js of a staged Vue plugin: on the wrong host it reports and throws, so nothing else of the
    plugin's module graph runs (DWC 3.6 catches the load error and disables the plugin; on 3.7 the script just stops)."""
    return (
        "// line-guard.js -- generated by build.py (tools/release_zips.py), DO NOT edit.\n"
        "if (" + guard_condition(line) + ") {\n  " + _report(plugin_id, line) + "\n"
        "  throw new Error(" + json.dumps("[%s] DWC %s build on the wrong DWC" % (plugin_id, line)) + ")\n}\n"
    )


def stage_guard(stage_dir, plugin_id, line):
    """Adds line-guard.js to stage/dwc-src and makes the stage's index.js import it before everything else."""
    src = os.path.join(stage_dir, "dwc-src")
    with open(os.path.join(src, "line-guard.js"), "w", encoding="utf-8", newline="\n") as f:
        f.write(guard_module(plugin_id, line))
    idx = os.path.join(src, "index.js")
    with open(idx, encoding="utf-8", newline="") as f:
        text = f.read()
    m = re.search(r"^import\b", text, re.M)
    if not m:
        raise SystemExit("%s: dwc-src/index.js has no import to put the line guard before" % plugin_id)
    text = text[:m.start()] + "import './line-guard.js'\n" + text[m.start():]
    with open(idx, "w", encoding="utf-8", newline="") as f:
        f.write(text)


# ---------------------------------------------------------------- manifest per line

def line_manifest(manifest, line):
    """The manifest of `manifest` for one DWC line. The builders are the only place that sets the per-line values; the source plugin.json
    files keep whatever they have and are never read as the release value."""
    if line not in LINES:
        raise ValueError(line)
    m = dict(manifest)
    m["dwcVersion"] = line
    if "sbcDsfVersion" in m:
        m["sbcDsfVersion"] = line
    deps = m.get("sbcPythonDependencies")
    if isinstance(deps, list):
        m["sbcPythonDependencies"] = [DSF_PYTHON[line] if re.match(r"dsf-python\b", d) else d for d in deps]
    return m


def release_name(plugin_id, version, line):
    return "%s-%s-dwc%s.zip" % (plugin_id, version, line)


# ---------------------------------------------------------------- finalize

def _entries(z):
    return [(i, z.read(i.filename)) for i in z.infolist() if not i.filename.endswith("/")]


def strip_map_comment(data):
    """Removes the trailing //# sourceMappingURL=... (or /*# ... */) comment of a js / css: its .map is not in the zip."""
    text = data.decode("utf-8")
    new = re.sub(r"\s*(//# sourceMappingURL=\S+|/\*# sourceMappingURL=[^*]*\*/)\s*$", "\n", text)
    return new.encode("utf-8") if new != text else data


def finalize_zip(src_zip, out_zip, line):
    """Rewrites a built line zip as the release zip of `line`: plugin.json with the line values and an exact dwcFiles list, no source maps,
    a .gz next to every dwc js/css of GZ_MIN_BYTES or more, fixed timestamps. Returns the manifest."""
    with zipfile.ZipFile(src_zip) as z:
        items = _entries(z)
    files = {i.filename: d for i, d in items}
    manifest = json.loads(files["plugin.json"].decode("utf-8"))
    out = {}
    for name, data in files.items():
        if name == "plugin.json" or name.endswith((".map", ".map.gz")):
            continue
        if name.startswith("dwc/") and name.endswith(".gz"):
            continue  # regenerated below, from the final bytes
        if name.startswith("dwc/") and name.endswith((".js", ".css")):
            data = strip_map_comment(data)
        out[name] = data
    for name in sorted(out):
        if name.startswith("dwc/") and name.endswith((".js", ".css")) and len(out[name]) >= GZ_MIN_BYTES:
            out[name + ".gz"] = gzip.compress(out[name], 9, mtime=0)
    manifest = line_manifest(manifest, line)
    manifest["dwcFiles"] = sorted(n[4:] for n in out if n.startswith("dwc/"))
    os.makedirs(os.path.dirname(os.path.abspath(out_zip)), exist_ok=True)
    tmp = out_zip + ".tmp"
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as z:
        def put(name, data):
            zi = zipfile.ZipInfo(name, ZIP_DATE)
            zi.compress_type = zipfile.ZIP_DEFLATED
            zi.external_attr = 0o644 << 16
            z.writestr(zi, data)
        put("plugin.json", json.dumps(manifest, indent=2, ensure_ascii=False))
        for name in sorted(out):
            put(name, out[name])
    os.replace(tmp, out_zip)
    return manifest


# ---------------------------------------------------------------- check

def _sbc_permissions(dwc_clone):
    """The permission names DWC accepts (SbcPermission enum of the 3.6 clone's object model), or None when the clone is not there."""
    p = os.path.join(dwc_clone or "", "node_modules", "@duet3d", "objectmodel", "dist", "plugins", "PluginManifest.d.ts")
    try:
        with open(p, encoding="utf-8") as f:
            text = f.read()
    except OSError:
        return None
    m = re.search(r"enum SbcPermission \{(.*?)\}", text, re.S)
    return set(re.findall(r"(\w+) = ", m.group(1))) if m else None


def check_manifest_rules(m, problems, perms=None):
    """checkManifest of DWC 3.6 and 3.7 (src/plugins/index.ts): id, name, author, version, permissions."""
    pid = m.get("id") or ""
    if not pid.strip() or len(pid) > 32 or not re.fullmatch(r"[a-zA-Z0-9 .\-_]+", pid):
        problems.append("manifest id %r is not accepted by DWC" % pid)
    name = m.get("name") or ""
    if not name.strip() or len(name) > 64 or not re.fullmatch(r"[a-zA-Z0-9 .\-_]+", name):
        problems.append("manifest name %r is not accepted by DWC" % name)
    if not (m.get("author") or "").strip():
        problems.append("manifest has no author")
    if not (m.get("version") or "").strip():
        problems.append("manifest has no version")
    if perms is not None:
        for p in m.get("sbcPermissions") or []:
            if p not in perms:
                problems.append("unsupported sbcPermission " + p)


def check_zip(path, line, plugin_id, version, official=False, perms=None, standalone=False):
    """Checks one release zip against everything known about how DWC 3.6.3 / 3.7.0 load a plugin. Returns (problems, info).
    official: a hand-written JS plugin built with the official 3.6 pipeline; standalone: a plugin that does not depend on the service."""
    problems = []
    info = {"zip_bytes": os.path.getsize(path)}
    expected = release_name(plugin_id, version, line)
    if os.path.basename(path) != expected:
        problems.append("file name %s, expected %s" % (os.path.basename(path), expected))
    if info["zip_bytes"] > MAX_ZIP_BYTES:
        problems.append("zip is %d bytes (limit %d)" % (info["zip_bytes"], MAX_ZIP_BYTES))
    try:
        z = zipfile.ZipFile(path)
    except zipfile.BadZipFile:
        return ["not a zip"], info
    with z:
        bad = z.testzip()
        if bad:
            problems.append("corrupt entry " + bad)
        names = [n for n in z.namelist() if not n.endswith("/")]
        if "plugin.json" not in names:
            return problems + ["no plugin.json"], info
        m = json.loads(z.read("plugin.json").decode("utf-8"))
        # --- manifest
        if m.get("id") != plugin_id:
            problems.append("manifest id %r, expected %r" % (m.get("id"), plugin_id))
        if m.get("version") != version:
            problems.append("manifest version %r, source version %r" % (m.get("version"), version))
        if m.get("dwcVersion") != line:
            problems.append("dwcVersion is %r, must be exactly %r (DWC compares by prefix: this decides which DWC accepts the zip)" % (m.get("dwcVersion"), line))
        other = [l for l in LINES if l != line][0]
        if str(m.get("dwcVersion", "")).startswith(other) or str(m.get("sbcDsfVersion", "")).startswith(other):
            problems.append("manifest carries the %s value in a %s zip" % (other, line))
        if "sbcDsfVersion" in m and m["sbcDsfVersion"] != line:
            problems.append("sbcDsfVersion is %r, must be %r" % (m["sbcDsfVersion"], line))
        if (m.get("sbcRequired") or m.get("sbcExecutable")) and m.get("sbcDsfVersion") != line:
            problems.append("a plugin with an SBC part needs sbcDsfVersion %r" % line)
        for d in m.get("sbcPythonDependencies") or []:
            if re.match(r"dsf-python\b", d) and d != DSF_PYTHON[line]:
                problems.append("sbcPythonDependencies pins %r, the %s line needs %r" % (d, line, DSF_PYTHON[line]))
        if plugin_id != SERVICE_ID:
            if not standalone and SERVICE_ID not in (m.get("dwcDependencies") or []):
                problems.append("dwcDependencies does not name " + SERVICE_ID)
        elif m.get("dwcDependencies"):
            problems.append("the service must not depend on a DWC plugin: " + str(m["dwcDependencies"]))
        check_manifest_rules(m, problems, perms)
        # --- file policy
        for n in names:
            if FORBIDDEN.search(n):
                problems.append("must not ship: " + n)
            if not (n == "plugin.json" or n.startswith(("dwc/", "sd/", "dsf/"))):
                problems.append("unexpected entry: " + n)
            if z.getinfo(n).file_size > MAX_FILE_BYTES:
                problems.append("%s is %d bytes (limit %d)" % (n, z.getinfo(n).file_size, MAX_FILE_BYTES))
        # --- listed vs present
        dwc = sorted(n[4:] for n in names if n.startswith("dwc/"))
        if sorted(m.get("dwcFiles") or []) != dwc:
            problems.append("dwcFiles does not match dwc/: " + str(sorted(set(m.get("dwcFiles") or []) ^ set(dwc))[:6]))
        for key, prefix in (("dsfFiles", "dsf/"), ("sdFiles", "sd/")):
            listed = sorted(m.get(key) or [])
            present = sorted(n[len(prefix):] for n in names if n.startswith(prefix))
            if listed != present:
                problems.append("%s does not match %s: %s" % (key, prefix, str(sorted(set(listed) ^ set(present))[:6])))
        if m.get("rrfFiles"):
            problems.append("rrfFiles is not empty (the SD files go in sdFiles)")
        # --- the bundle
        js = [n for n in names if n.startswith("dwc/") and n.endswith(".js")]
        css = [n for n in names if n.startswith("dwc/") and n.endswith(".css")]
        info.update(js=js, css=css)
        main = [n for n in js if plugin_id in n]
        if len(js) != 1 or len(main) != 1:
            problems.append("expected exactly one dwc js whose name contains %s, found %s (DWC 3.6 loads only the first match, 3.7 injects all)" % (plugin_id, js))
        if len(css) > 1:
            problems.append("more than one css: %s" % css)
        if main:
            code = z.read(main[0]).decode("utf-8", "replace")
            info["js_bytes"] = len(code.encode("utf-8"))
            if "sourceMappingURL" in code:
                problems.append("the bundle still points to a source map")
            # the minifiers requote string literals, so the marker is looked for as text, not as a JS literal
            if "data-workshop-line-guard" not in code or ("%s %s build needs DWC %s.x" % (plugin_id, line, line)) not in code:
                problems.append("the bundle has no run-time guard for %s" % line)
            if "unknown host (neither DWC 3.7 nor DWC 3.6)" in code or "function run36()" in code:
                problems.append("the bundle contains the universal host switch (tools/universal_zip.py output)")
            if line == "3.6":
                if "webpackChunkduetwebcontrol" not in code:
                    problems.append("the 3.6 bundle is not a DWC 3.6 webpack chunk")
                if official and "registerPluginLocalization" not in code:
                    problems.append("the 3.6 bundle does not register its i18n catalogs (registerPluginLocalization): raw plugins.* keys in the sidebar (build it with the official pipeline)")
            else:
                if "webpackChunkduetwebcontrol" in code:
                    problems.append("the 3.7 bundle is a DWC 3.6 webpack chunk")
            for c in css:
                if "sourceMappingURL" in z.read(c).decode("utf-8", "replace"):
                    problems.append(c + " points to a source map")
        # --- .gz policy
        for n in js + css:
            data = z.read(n)
            gz = n + ".gz"
            if len(data) >= GZ_MIN_BYTES:
                if gz not in names:
                    problems.append("%s (%d bytes) has no .gz companion" % (n, len(data)))
                elif gzip.decompress(z.read(gz)) != data:
                    problems.append(gz + " does not decompress to " + n)
            elif gz in names:
                problems.append(gz + " exists for a small file")
        info["total_bytes"] = sum(z.getinfo(n).file_size for n in names)
    return problems, info


# ---------------------------------------------------------------- sums

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def write_sums(folder):
    """SHA256SUMS.txt of every .zip in `folder` (sha256sum format, so `sha256sum -c SHA256SUMS.txt` works)."""
    names = sorted(n for n in os.listdir(folder) if n.endswith(".zip"))
    with open(os.path.join(folder, "SHA256SUMS.txt"), "w", encoding="utf-8", newline="\n") as f:
        for n in names:
            f.write("%s  %s\n" % (sha256_file(os.path.join(folder, n)), n))
    return names


def check_sums(folder):
    """Problems between SHA256SUMS.txt and the zips of the folder."""
    p = os.path.join(folder, "SHA256SUMS.txt")
    if not os.path.isfile(p):
        return ["no SHA256SUMS.txt in " + folder]
    listed = {}
    with open(p, encoding="utf-8") as f:
        for line in f:
            if line.strip():
                h, n = line.strip().split(None, 1)
                listed[n.strip()] = h
    problems = []
    zips = sorted(n for n in os.listdir(folder) if n.endswith(".zip"))
    for n in zips:
        if n not in listed:
            problems.append("SHA256SUMS.txt does not list " + n)
        elif listed[n] != sha256_file(os.path.join(folder, n)):
            problems.append("SHA256SUMS.txt hash of %s is stale" % n)
    for n in listed:
        if n not in zips:
            problems.append("SHA256SUMS.txt lists a missing zip " + n)
    return problems
